'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Returns the first index of a specified search element in a one-dimensional double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the search element.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Float64Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var searchElement = scalar2ndarray( 2.0, {
*     'dtype': 'float64'
* });
*
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'int32'
* });
*
* var v = dindexOf( [ x, searchElement, fromIndex ] );
* // returns 3
*/
function dindexOf( arrays ) {
	var searchElement = arrays[ 1 ];
	var fromIndex = arrays[ 2 ];
	var x = arrays[ 0 ];

	return addon( getData( x ), serialize( x ), getData( searchElement ), serialize( searchElement ), getData( fromIndex ), serialize( fromIndex ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = dindexOf;
